CREATE TABLE ${primehrSchema}.evidence_framework (id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT uk_evidence_framework_code UNIQUE(agency_id,normalized_code));
CREATE TABLE ${primehrSchema}.evidence_framework_version (id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,framework_id VARCHAR(36) NOT NULL,definition_version INT NOT NULL,supersedes_id VARCHAR(36),title VARCHAR(200) NOT NULL,description VARCHAR(2000),issuing_body VARCHAR(250) NOT NULL,legal_basis VARCHAR(2000) NOT NULL,authority_reference VARCHAR(250) NOT NULL,internal_use_disclaimer VARCHAR(2000) NOT NULL,content_revision INT NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL,effective_from DATE,effective_to DATE,published_by VARCHAR(100),published_at DATETIMEOFFSET,retired_by VARCHAR(100),retired_at DATETIMEOFFSET,retirement_reason VARCHAR(1000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_evidence_framework_root FOREIGN KEY(framework_id) REFERENCES ${primehrSchema}.evidence_framework(id),CONSTRAINT fk_evidence_framework_prior FOREIGN KEY(supersedes_id) REFERENCES ${primehrSchema}.evidence_framework_version(id),CONSTRAINT uk_evidence_framework_version UNIQUE(agency_id,framework_id,definition_version),CONSTRAINT ck_evidence_framework_values CHECK(definition_version>=1 AND content_revision>=0),CONSTRAINT ck_evidence_framework_status CHECK(status IN('DRAFT','PUBLISHED','RETIRED')),CONSTRAINT ck_evidence_framework_dates CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from),CONSTRAINT ck_evidence_framework_lifecycle CHECK((status='DRAFT' AND effective_from IS NULL AND published_at IS NULL) OR (status IN('PUBLISHED','RETIRED') AND effective_from IS NOT NULL AND published_at IS NOT NULL)));
CREATE INDEX ix_evidence_framework_effective ON ${primehrSchema}.evidence_framework_version(agency_id,status,effective_from,effective_to);
CREATE TABLE ${primehrSchema}.evidence_pillar (id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,framework_version_id VARCHAR(36) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,title VARCHAR(200) NOT NULL,description VARCHAR(2000),display_order INT NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_evidence_pillar_framework FOREIGN KEY(framework_version_id) REFERENCES ${primehrSchema}.evidence_framework_version(id),CONSTRAINT uk_evidence_pillar_code UNIQUE(agency_id,framework_version_id,normalized_code),CONSTRAINT uk_evidence_pillar_order UNIQUE(agency_id,framework_version_id,display_order),CONSTRAINT ck_evidence_pillar_order CHECK(display_order>=1));
CREATE INDEX ix_evidence_pillar_framework ON ${primehrSchema}.evidence_pillar(agency_id,framework_version_id,display_order);
CREATE TABLE ${primehrSchema}.evidence_governance_level (id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,framework_version_id VARCHAR(36) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,label VARCHAR(200) NOT NULL,description VARCHAR(2000) NOT NULL,reference_only BIT NOT NULL DEFAULT 1,display_order INT NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_evidence_level_framework FOREIGN KEY(framework_version_id) REFERENCES ${primehrSchema}.evidence_framework_version(id),CONSTRAINT uk_evidence_level_code UNIQUE(agency_id,framework_version_id,normalized_code),CONSTRAINT uk_evidence_level_order UNIQUE(agency_id,framework_version_id,display_order),CONSTRAINT ck_evidence_level_reference CHECK(reference_only=1),CONSTRAINT ck_evidence_level_order CHECK(display_order>=1));
CREATE INDEX ix_evidence_level_framework ON ${primehrSchema}.evidence_governance_level(agency_id,framework_version_id,display_order);
CREATE TABLE ${primehrSchema}.evidence_indicator (id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,framework_version_id VARCHAR(36) NOT NULL,pillar_id VARCHAR(36) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,title VARCHAR(300) NOT NULL,description VARCHAR(2000),evaluation_guidance VARCHAR(4000) NOT NULL,display_order INT NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_evidence_indicator_framework FOREIGN KEY(framework_version_id) REFERENCES ${primehrSchema}.evidence_framework_version(id),CONSTRAINT fk_evidence_indicator_pillar FOREIGN KEY(pillar_id) REFERENCES ${primehrSchema}.evidence_pillar(id),CONSTRAINT uk_evidence_indicator_code UNIQUE(agency_id,framework_version_id,normalized_code),CONSTRAINT uk_evidence_indicator_order UNIQUE(agency_id,pillar_id,display_order),CONSTRAINT ck_evidence_indicator_order CHECK(display_order>=1));
CREATE INDEX ix_evidence_indicator_pillar ON ${primehrSchema}.evidence_indicator(agency_id,framework_version_id,pillar_id,display_order);
CREATE TABLE ${primehrSchema}.evidence_requirement (id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,framework_version_id VARCHAR(36) NOT NULL,indicator_id VARCHAR(36) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,title VARCHAR(300) NOT NULL,evidence_guidance VARCHAR(4000) NOT NULL,evidence_type VARCHAR(30) NOT NULL,recurrence_months INT,freshness_days INT,required BIT NOT NULL,allows_not_applicable BIT NOT NULL,display_order INT NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_evidence_requirement_framework FOREIGN KEY(framework_version_id) REFERENCES ${primehrSchema}.evidence_framework_version(id),CONSTRAINT fk_evidence_requirement_indicator FOREIGN KEY(indicator_id) REFERENCES ${primehrSchema}.evidence_indicator(id),CONSTRAINT uk_evidence_requirement_code UNIQUE(agency_id,framework_version_id,normalized_code),CONSTRAINT uk_evidence_requirement_order UNIQUE(agency_id,indicator_id,display_order),CONSTRAINT ck_evidence_requirement_type CHECK(evidence_type IN('LIVE_TRANSACTION','REPORT','DOCUMENT','POLICY','OTHER')),CONSTRAINT ck_evidence_requirement_values CHECK(display_order>=1 AND (recurrence_months IS NULL OR recurrence_months>=1) AND (freshness_days IS NULL OR freshness_days>=1)));
CREATE INDEX ix_evidence_requirement_indicator ON ${primehrSchema}.evidence_requirement(agency_id,framework_version_id,indicator_id,display_order);
